#!/usr/bin/env python3
from cyclopts import App

app = App()

@app.default
def status():
    """Show the status of the service."""
    print("Service is running")

@app.command
def start():
    """Start the service."""
    print("Service started")

@app.command
def stop():
    """Stop the service."""
    print("Service stopped")

if __name__ == "__main__":
    app()
